package com.djibtout.backend.security;
import com.djibtout.backend.entity.*;import com.djibtout.backend.repository.*;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;
@Component public class ValidatedSellerFilter extends OncePerRequestFilter{
 private final UserRepository users;private final SellerStoreRepository stores;public ValidatedSellerFilter(UserRepository u,SellerStoreRepository s){users=u;stores=s;}
 @Override protected boolean shouldNotFilter(HttpServletRequest r){String p=r.getRequestURI();if(p.equals("/api/seller/store")||p.startsWith("/api/seller/documents")||p.startsWith("/api/auth/")||p.startsWith("/api/public/"))return true;boolean sellerApi=p.startsWith("/api/seller/"),catalogWrite=p.startsWith("/api/products")&&!"GET".equals(r.getMethod()),upload=p.startsWith("/api/upload");return !(sellerApi||catalogWrite||upload);}
 @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{var auth=org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication();if(auth==null||!auth.isAuthenticated()){chain.doFilter(req,res);return;}User u=users.findByEmail(auth.getName()).orElse(null);if(u==null||u.getRole()==Role.ADMIN||u.getRole()!=Role.SELLER){chain.doFilter(req,res);return;}SellerStore store=stores.findBySeller(u).orElse(null);if(store==null||!store.isValidated()){res.setStatus(403);res.setContentType("application/json;charset=UTF-8");res.getWriter().write("{\"message\":\"Votre boutique doit être validée avant cette opération.\"}");return;}chain.doFilter(req,res);}
}
